#!/bin/bash
# usage: build_teaser.sh scene.png out.mp4
cd /home/claude/sc-assets
D=/tmp/claude-0/-home-claude/929d7033-9029-506c-a3fe-b34391199f55/scratchpad
P=/usr/share/fonts/truetype/google-fonts/Poppins-Bold.ttf
ffmpeg -y -loglevel error -loop 1 -framerate 24 -t 8 -i "$1" -i $D/3c.wav -filter_complex "[0:v]scale=1080:1872:flags=lanczos,eq=brightness='${3:--0.05}+0.03*sin(t*2.1)',vignette=PI/5,drawtext=fontfile=$P:text='COMING SOON':fontsize=84:fontcolor=white:shadowcolor=black:shadowx=4:shadowy=4:x=(w-text_w)/2:y=h*0.82:alpha='if(lt(t,3),0,min(1,(t-3)/1.2))',fade=t=in:st=0:d=1.5,fade=t=out:st=7.2:d=0.8:color=black,format=yuv420p[v1];color=c=black:s=1080x1872:d=4.4:r=24,format=rgba[bk];movie=brand/logos/SC_full_logo_chrome_transparent.png,scale=860:-1,format=rgba,loop=loop=-1:size=1,fps=24,trim=duration=4.4,setpts=PTS-STARTPTS,fade=t=in:st=0.4:d=2.4:alpha=1[lg];[bk][lg]overlay=(W-w)/2:(H-h)/2-110:shortest=1,drawtext=fontfile=$P:text='FOLLOW TO SEE OUR':fontsize=58:fontcolor=white:x=(w-text_w)/2:y=h*0.58:alpha='if(lt(t,2.2),0,min(1,(t-2.2)/0.9))',drawtext=fontfile=$P:text='CHRISTMAS TRAILER':fontsize=58:fontcolor=white:x=(w-text_w)/2:y=h*0.58+80:alpha='if(lt(t,2.2),0,min(1,(t-2.2)/0.9))',drawtext=fontfile=$P:text='stiffcompetition.shop':fontsize=54:fontcolor=white:x=(w-text_w)/2:y=h*0.58+210:alpha='if(lt(t,2.8),0,min(1,(t-2.8)/0.9))',format=yuv420p[v2];[v1][v2]concat=n=2:v=1:a=0[v];[1:a]atrim=0:12.4,asetpts=PTS-STARTPTS[a]" -map "[v]" -map "[a]" -c:v libx264 -preset veryfast -crf 24 -r 24 -c:a aac -b:a 160k -t 12.4 "$2"
